changeSet.sql:
INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Compras', 'PURCHASES', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'PURCHASES');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver proveedores', 'supplier.read', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'supplier.read');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Crear proveedores', 'supplier.create', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'supplier.create');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Editar proveedores', 'supplier.update', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'supplier.update');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Eliminar proveedores', 'supplier.delete', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'supplier.delete');
